        m317Require(count($p)===1&&$p[0]['Title']===$name,'Chemical response does not uniquely match selected label.');$p=$p[0];$access=gmdate('Y-m-d\TH:i:s\Z',filemtime($pfile));
        $sources[]=['type'=>'pubchem','proposed_tier'=>1,'tier_status'=>'GOVERNMENT_CHEMICAL_REGISTRY_PROPOSAL_REQUIRES_APPRAISAL','authority'=>'NIH / National Library of Medicine / NCBI PubChem','title'=>$p['Title'],'publisher_version'=>null,'publication_date'=>null,'accessed_at_utc'=>$access,'url'=>'https://pubchem.ncbi.nlm.nih.gov/compound/'.$p['CID'],'captured_url'=>'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/'.$name.'/property/Title,MolecularFormula,InChI,InChIKey/JSON','locator'=>'PropertyTable.Properties[0]; CID '.$p['CID'].'; Title/MolecularFormula/InChI/InChIKey','raw_file'=>'storage/logs/medicine317-preparation/'.$id.'-pubchem.json','source_sha256'=>hash_file('sha256',$pfile),'byte_length'=>filesize($pfile),'observed_identity'=>$p,'supported_purpose'=>'Traceable government chemical-record name, formula and structural identifier; mapping to the exact KOBI entity remains unappraised.','currentness'=>'Retrieved live; no publisher edition or latest-authoritative status established.','proposed_evidence'=>['kind'=>'identity','issuer'=>'NIH_NLM_PUBCHEM_PROPOSED','record'=>'CID '.$p['CID'],'version'=>'retrieval-snapshot '.$access.' (no publisher version exposed)','locator'=>'PropertyTable.Properties[0]; CID '.$p['CID'],'source_sha256'=>hash_file('sha256',$pfile)]];
        $xmlfile=M317_SOURCE_DIR.'/'.$id.'-dailymed.xml';$d=new DOMDocument();m317Require($d->load($xmlfile,LIBXML_NONET),'Invalid captured SPL.');$x=new DOMXPath($d);$x->registerNamespace('h','urn:hl7-org:v3');
        $text=fn($q)=>trim(preg_replace('/\s+/u',' ',$x->evaluate('string('.$q.')')));$set=$text('/h:document/h:setId/@root');$version=$text('/h:document/h:versionNumber/@value');$date=$text('/h:document/h:effectiveTime/@value');$ingredients=[];
