        $sources[]=['type'=>'dailymed_spl','proposed_tier'=>4,'tier_status'=>'MANUFACTURER_OR_PACKAGER_LABEL_NOT_PROMOTED_BY_GOVERNMENT_HOSTING','authority'=>'DailyMed / NIH National Library of Medicine (government custodian)','originator'=>$text('/h:document/h:author/h:assignedEntity/h:representedOrganization/h:name'),'title'=>$pageTitle,'document_id'=>$text('/h:document/h:id/@root'),'set_id'=>$set,'publisher_version'=>$version,'effective_date'=>$date,'publication_date'=>null,'accessed_at_utc'=>gmdate('Y-m-d\TH:i:s\Z',filemtime($xmlfile)),'url'=>'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid='.$set.'&version='.$version,'captured_url'=>'https://dailymed.nlm.nih.gov/dailymed/services/v2/spls/'.$set.'.xml','locator'=>'SPL document setId/versionNumber; DESCRIPTION section code 34089-3; manufacturedProduct/ingredient[@classCode=ACTIB]/ingredientSubstance/name and code','raw_file'=>'storage/logs/medicine317-preparation/'.$id.'-dailymed.xml','source_sha256'=>hash_file('sha256',$xmlfile),'byte_length'=>filesize($xmlfile),'observed_active_ingredients'=>array_values($ingredients),'supported_purpose'=>'Named active ingredient and one distinct active ingredient in the captured labelled product(s); not proof of every formulation or the exact KOBI registry entity.','currentness'=>'Exact live SPL revision captured; not independently confirmed latest FDA-approved labelling or source appraisal currency.','proposed_evidence'=>['kind'=>'identity','issuer'=>'NLM_DAILYMED_MANUFACTURER_PROPOSED','record'=>'SPL '.$set,'version'=>'SPL '.$version.' effective '.$date,'locator'=>'DESCRIPTION (34089-3); active ingredient XML nodes','source_sha256'=>hash_file('sha256',$xmlfile)]];
